/**
 * Recording that money went out.
 *
 * Three rules hold this together, and all three are things the legacy app
 * either does differently or does not do at all.
 *
 * **The ledger is the truth.** How much has been paid is a sum of rows, never
 * a stored figure. The sheet keeps a Paid Total column because it cannot join;
 * copying that here would reproduce its drift, where the cached number and the
 * payments it claims to describe can disagree with nobody noticing.
 *
 * **A payment is recorded once.** Every attempt carries a key generated by the
 * browser, and a unique constraint turns a double click, a retry after a
 * timeout, and a refreshed form into one row rather than three. A script lock
 * -- what the legacy app relies on -- prevents two payments at the same
 * instant, which is not the same problem.
 *
 * **Nothing is deleted.** A payment recorded by mistake is reversed with a
 * negative row that says what it reverses. The history of what was recorded,
 * and when, stays answerable, which is the whole point of a financial record.
 */
import {
  BadRequestException, ConflictException, ForbiddenException, Injectable, Logger,
  NotFoundException,
} from '@nestjs/common';
import { Principal, can } from '../../common/auth';
import { one, query, tx } from '../../common/db';
import { AuditService, NotificationsService } from '../../core/core.module';
import { lensFor } from './projection';
import { ZohoQueueService } from './zoho/zoho-queue.service';
import { ZohoAccountsService } from './zoho/accounts.service';

const RECORD = 'finance.payment.record';
const MANAGE = 'finance.request.manage';
const REPORT = 'finance.report.view';
const PURCHASES = 'finance.purchases.decide';

export interface PaymentInput {
  amount: number;
  paidAt?: string;
  reference?: string;
  note?: string;
  receiptFileId?: string;
  /** Generated per attempt by the browser. Two attempts, one key, one payment. */
  idempotencyKey: string;

  /* Which Zoho accounts this payment moves money between. Chosen here rather
     than configured, because the expense account differs per request. */
  zohoPaidThroughAccountId?: string;
  zohoExpenseAccountId?: string;
  zohoToAccountId?: string;
  zohoBranchId?: string;
}

@Injectable()
export class FinancePaymentsService {
  private readonly log = new Logger('FinancePayments');

  constructor(
    private readonly notifications: NotificationsService,
    private readonly audit: AuditService,
    private readonly zoho: ZohoQueueService,
    private readonly accounts: ZohoAccountsService,
  ) {}

  /**
   * Record a payment against an approved request.
   *
   * Done inside a transaction with the request locked, because the check that
   * matters -- that this payment does not take the total past what was asked
   * for -- is only true if nothing else is being recorded at the same moment.
   */
  async record(p: Principal, requestId: string, dto: PaymentInput) {
    if (!can(p, RECORD)) {
      throw new ForbiddenException('Only Finance can record a payment.');
    }
    if (!(dto.amount > 0)) {
      throw new BadRequestException('A payment must be more than zero.');
    }
    if (!dto.idempotencyKey?.trim()) {
      throw new BadRequestException('A payment needs a key so it cannot be recorded twice.');
    }

    /* Checked before the payment is written, not when it is posted. A wrong
       account found at posting time is a dead queue item hours later, by which
       point the person who could have corrected it has moved on. */
    await this.checkAccounts(requestId, dto);

    try {
      const result = await tx(async (c) => {
        const { rows } = await c.query(
          `SELECT * FROM fin_requests WHERE id=$1 AND deleted_at IS NULL FOR UPDATE`,
          [requestId]);
        const r = rows[0];
        if (!r) throw new NotFoundException('No such request.');

        if (r.approval_state !== 'APPROVED') {
          throw new BadRequestException(
            r.approval_state === 'REJECTED'
              ? 'This request was rejected; nothing should be paid against it.'
              : 'This request has not been approved yet.');
        }
        if (r.requested_amount === null) {
          throw new BadRequestException(
            'This request has not been priced, so there is nothing to pay.');
        }

        const { rows: sums } = await c.query(
          `SELECT COALESCE(sum(amount), 0) AS paid FROM fin_payments WHERE request_id=$1`,
          [requestId]);
        const paid = Number(sums[0].paid);
        const asked = Number(r.requested_amount);
        const remaining = asked - paid;

        /* Overpaying is almost always a typo -- a figure keyed into the wrong
           box -- and is much harder to notice afterwards than to refuse now. */
        if (dto.amount > remaining + 0.005) {
          throw new BadRequestException(
            `Only ${remaining.toFixed(2)} is left to pay on this request.`);
        }

        const { rows: out } = await c.query(
          `INSERT INTO fin_payments
             (request_id, amount, paid_at, reference, note, recorded_by_id,
              receipt_file_id, idempotency_key,
              zoho_paid_through_account_id, zoho_expense_account_id,
              zoho_to_account_id, zoho_branch_id)
           VALUES ($1,$2,COALESCE($3, now()),$4,$5,$6,$7,$8,$9,$10,$11,$12)
           RETURNING *`,
          [requestId, dto.amount, dto.paidAt ?? null, dto.reference ?? null,
           dto.note ?? null, p.id, dto.receiptFileId ?? null, dto.idempotencyKey.trim(),
           dto.zohoPaidThroughAccountId ?? null, dto.zohoExpenseAccountId ?? null,
           dto.zohoToAccountId ?? null, dto.zohoBranchId ?? null]);

        return { payment: out[0], request: r };
      });

      await this.audit.write({
        actorId: p.id, moduleKey: 'finance', action: 'payment.record',
        entityType: 'fin_payment', entityId: result.payment.id,
        payload: {
          reference: result.request.reference,
          amount: Number(result.payment.amount),
        },
      });

      /* Queued after the payment is committed, never inside its transaction.
         The payment is a fact about our own records: it must not be held up,
         or undone, by anything to do with Zoho. A queue row that fails to be
         written is worth a log line, not a lost payment. */
      await this.zoho.enqueuePayment(result.payment.id)
        .catch((e) => this.log.error(
          `payment ${result.payment.id} was recorded but not queued for Zoho: `
          + `${e?.message ?? e}`));

      await this.tellTheRequester(result.request.id);
      return this.view(p, result.payment);
    } catch (e: any) {
      /* The same payment arriving twice. Returning the one that exists is
         kinder and safer than an error: the caller wanted this payment
         recorded, and it is. */
      if (e?.code === '23505') {
        const existing = await one<any>(
          `SELECT * FROM fin_payments WHERE idempotency_key=$1`, [dto.idempotencyKey.trim()]);
        if (existing) {
          this.log.log(`payment ${dto.idempotencyKey} was already recorded; returning it`);
          return this.view(p, existing);
        }
        throw new ConflictException('That payment has already been recorded.');
      }
      throw e;
    }
  }

  /**
   * Are the chosen accounts ones that may be used this way?
   *
   * Skipped entirely while the cache is empty or Zoho is switched off: a
   * server with no Zoho connection must still be able to record that money
   * went out, and the queue reports what it could not post.
   */
  private async checkAccounts(requestId: string, dto: PaymentInput) {
    if (!(await this.accounts.ready())) return;

    const r = await one<any>(`SELECT type FROM fin_requests WHERE id=$1`, [requestId]);
    const kind = r?.type === 'Petty Cash' ? 'CUSTODY'
               : r?.type === 'Vendors Payments' ? 'VENDOR' : 'EXPENSE';

    if (dto.zohoPaidThroughAccountId
        && !(await this.accounts.check(dto.zohoPaidThroughAccountId, 'payFrom'))) {
      throw new BadRequestException('That is not an account money can be paid from.');
    }
    if (kind === 'CUSTODY' && dto.zohoToAccountId
        && !(await this.accounts.check(dto.zohoToAccountId, 'custody'))) {
      throw new BadRequestException('That is not a petty-cash account.');
    }
    if (kind === 'EXPENSE' && dto.zohoExpenseAccountId
        && !(await this.accounts.check(dto.zohoExpenseAccountId, 'expense'))) {
      throw new BadRequestException('That is not an expense account.');
    }
  }

  /**
   * Undo a payment that should not have been recorded.
   *
   * A negative row rather than a deletion. The sum comes out right and the
   * record of what happened survives -- a payment that was entered, noticed and
   * reversed is a different thing from one that never existed, and an auditor
   * is entitled to see which it was.
   */
  async reverse(p: Principal, paymentId: string, reason: string) {
    if (!can(p, RECORD)) {
      throw new ForbiddenException('Only Finance can reverse a payment.');
    }
    if (!reason?.trim()) throw new BadRequestException('Say why it is being reversed.');

    const original = await one<any>(`SELECT * FROM fin_payments WHERE id=$1`, [paymentId]);
    if (!original) throw new NotFoundException('No such payment.');
    if (original.reversal_of_id) {
      throw new BadRequestException('That is itself a reversal.');
    }

    try {
      const row = await one<any>(
        `INSERT INTO fin_payments
           (request_id, amount, paid_at, note, recorded_by_id, idempotency_key,
            reversal_of_id)
         VALUES ($1,$2,now(),$3,$4,$5,$6) RETURNING *`,
        [original.request_id, -Number(original.amount), reason.trim(), p.id,
         `reversal:${paymentId}`, paymentId]);

      /* On the request's own conversation as well. An audit log answers "what
         happened" for whoever goes looking; a note answers it for whoever is
         simply reading the request, which is everybody. */
      await query(
        `INSERT INTO fin_request_notes (request_id, author_id, body) VALUES ($1,$2,$3)`,
        [original.request_id, p.id,
         `Payment reversed: ${reason.trim()}`.slice(0, 2000)]);

      await this.audit.write({
        actorId: p.id, moduleKey: 'finance', action: 'payment.reverse',
        entityType: 'fin_payment', entityId: paymentId,
        payload: { amount: Number(original.amount), reason },
      });
      return this.view(p, row);
    } catch (e: any) {
      if (e?.code === '23505') {
        throw new BadRequestException('That payment has already been reversed.');
      }
      throw e;
    }
  }

  /**
   * The payments on one request, and what they add up to.
   *
   * Subject to the same privacy rule as everything else: a department that
   * never sees money does not see a payment history either, which would be the
   * same figures by another route.
   */
  async forRequest(p: Principal, requestId: string) {
    const r = await one<any>(
      `SELECT r.*, f.lite AS department_is_lite
         FROM fin_requests r
         LEFT JOIN fin_departments f ON f.department_id = r.department_id
        WHERE r.id = $1 AND r.deleted_at IS NULL`, [requestId]);
    if (!r) throw new NotFoundException('No such request.');

    const maySeeRequest = r.requester_id === p.id
      || (p.managedDepartmentIds ?? []).includes(r.department_id)
      || can(p, MANAGE) || can(p, REPORT) || can(p, PURCHASES);
    if (!maySeeRequest) throw new NotFoundException('No such request.');

    const lens = lensFor(p, {
      own: r.requester_id === p.id,
      managesDepartment: (p.managedDepartmentIds ?? []).includes(r.department_id),
      requestingDepartmentIsLite: !!r.department_is_lite,
    });
    if (!lens.money) {
      return { payments: [], paid: null, remaining: null, hidden: true };
    }

    const rows = await query<any>(
      `SELECT pm.*, u.full_name AS recorded_by_name
         FROM fin_payments pm
         JOIN core_users u ON u.id = pm.recorded_by_id
        WHERE pm.request_id = $1 ORDER BY pm.paid_at, pm.created_at`, [requestId]);

    const paid = rows.reduce((n, x) => n + Number(x.amount), 0);
    const asked = r.requested_amount === null ? null : Number(r.requested_amount);

    return {
      payments: rows.map((x) => this.view(p, x)),
      paid,
      remaining: asked === null ? null : Math.max(asked - paid, 0),
      hidden: false,
    };
  }

  /** What is approved and still owing, for whoever pays it. */
  async outstanding(p: Principal) {
    if (!can(p, RECORD) && !can(p, MANAGE) && !can(p, REPORT)) {
      throw new ForbiddenException('You cannot see the payment list.');
    }
    const rows = await query<any>(
      `SELECT r.id, r.reference, r.description, r.due_date, r.requested_amount,
              r.type, r.vendor_name, r.payment_method, r.payment_details,
              d.name AS department_name,
              COALESCE(sum(pm.amount), 0) AS paid
         FROM fin_requests r
         JOIN core_departments d ON d.id = r.department_id
         LEFT JOIN fin_payments pm ON pm.request_id = r.id
        WHERE r.deleted_at IS NULL
          AND r.approval_state = 'APPROVED'
          AND r.payment_state <> 'PAID'
        GROUP BY r.id, d.name
        ORDER BY r.due_date, r.created_at`);

    return rows.map((r) => ({
      id: r.id,
      reference: r.reference,
      description: r.description,
      departmentName: r.department_name,
      type: r.type,
      vendorName: r.vendor_name,
      paymentMethod: r.payment_method,
      paymentDetails: r.payment_details,
      dueDate: r.due_date instanceof Date
        ? r.due_date.toISOString().slice(0, 10) : r.due_date,
      requestedAmount: r.requested_amount === null ? null : Number(r.requested_amount),
      paid: Number(r.paid),
      remaining: r.requested_amount === null
        ? null : Number(r.requested_amount) - Number(r.paid),
    }));
  }

  private view(p: Principal, row: any) {
    return {
      id: row.id,
      requestId: row.request_id,
      amount: Number(row.amount),
      paidAt: new Date(row.paid_at).toISOString(),
      reference: row.reference ?? null,
      note: row.note ?? null,
      recordedBy: row.recorded_by_name ?? null,
      isReversal: !!row.reversal_of_id,
      canReverse: !row.reversal_of_id && can(p, RECORD),
    };
  }

  /** The requester is told money moved, never how much: see projection.ts. */
  private async tellTheRequester(requestId: string) {
    try {
      const r = await one<any>(
        `SELECT reference, requester_id, payment_state FROM fin_requests WHERE id=$1`,
        [requestId]);
      if (!r) return;
      await this.notifications.notify(
        r.requester_id, 'finance',
        r.payment_state === 'PAID'
          ? `${r.reference} has been paid in full`
          : `${r.reference}: a payment has been made`,
        '', 'INFO', `/finance/requests/${requestId}`);
    } catch (e: any) {
      this.log.warn(`could not notify about payment on ${requestId}: ${e?.message ?? e}`);
    }
  }
}